from _lib import File
F=File('pre2020_husqvarna','o-hq','Husqvarna FC 450, FC 350 and FC 250 2014-2019: how each differs from its KTM sibling, dyno and weight, tester settings, maps, known problems and fixes (knowledge push 2026-11)','Husqvarna',['FC 450','FC 350','FC 250','TC 125','TC 250'],list(range(2014,2020)))
R=F.R; M='magazine'
FC=['FC 450','FC 350','FC 250']

# ---------------- shared
s=F.src(M,"Motocross Action - 2014 Husqvarna FC450 test","https://motocrossactionmag.com/2014-test-ride-husqvarna-fc450","2013")
R('identity','2014-2015 FC models against the KTM SX-F',FC,[2014,2015],"The 2014-2015 Austrian-built Husqvarna FC models are the KTM SX-F of the same year with these differences: a polyamide composite subframe instead of aluminium, a left side panel that is also the airbox cover (sealed, where the KTM is vented), D.I.D DirtStar rims instead of Excel, a 20 mm rear axle on 2014 bikes (KTM 25 mm), two seat bolts hidden in the hand-holds, a handlebar switch for two ignition maps as standard, a muffler with extra sound-deadening screens, and white bodywork with its own tank and seat. From 2015 they carry Neken bars and the WP 4CS fork.",{'subframe':'polyamide composite','rims':'D.I.D DirtStar','map_switch':'standard'},'OEM',s)
R('known_issues','2014-2015 FC weak points and fixes',FC,[2014,2015],"Tester findings on the 2014-2015 FC models: the sealed airbox and screened muffler choke the low-to-mid (drill holes in the left side panel, remove the backfire screen and fit a fire-retardant filter, pull the muffler screen), the rear fender cracks if the bike is lifted by it (use the hand-holds), the subframe bolt bulge catches boots, the air-filter cage is easy to seat wrong, the shift lever tip is too low stock and too high one spline up, the shock preload ring deforms, and the rear sprocket bolts and the spoke by the rim lock need checking before every ride.",{},'TUNER',s)
s17=F.src(M,"Motocross Action - 2018 Husqvarna FC450 race test","https://motocrossactionmag.com/mxa-race-test-2018-husqvarna-fc450","2017")
R('identity','2016-2018 FC models against the KTM SX-F',FC,[2016,2017,2018],"The 2016-2018 FC models share frame, engine, geometry and suspension hardware with the KTM SX-F and differ in: a three-piece composite subframe and airbox that is nearly sealed, a Magura hydraulic clutch (KTM uses Brembo), Pro Taper bars with a slightly lower, shorter bend, a seat about 5 mm lower, D.I.D DirtStar rims, heavier GFK brake discs, a muffler with internal cones where the KTM's is straight-through (FC 450), and their own suspension settings. They weigh about 2 lb more than the KTM and feel a little softer and more forgiving in the chassis.",{'clutch':'Magura hydraulic','subframe':'three-piece composite','rims':'D.I.D DirtStar','discs':'GFK'},'OEM',s17)
R('known_issues','2016-2019 FC weak points and fixes',FC,[2016,2017,2018,2019],"Tester findings on the 2016-2019 FC models: the Magura clutch slave seal can fail (the KTM Brembo slave piston and seal kit fits and cures it), the airbox restricts the low-to-mid (drill the cover, or on the FC 450 also remove the muffler cones), loose spacers fall out when the seat or right side-panel bolts are removed (glue them in), the exhaust needs the shock out to remove through 2018, sprocket bolts and spokes loosen, tie-down hooks can crimp the front brake hose, and the 2017 right side panel could melt on the exhaust until a heat shield was added for 2018.",{'clutch_fix':'KTM Brembo slave piston and seal'},'TUNER',s17)

# ---------------- FC 450
R('power_feel','2014 FC 450 dyno',['FC 450'],[2014],"On a magazine dyno the 2014 FC 450 made 56.95 hp, the same as the KTM 450 SX-F it shares its engine with. Mild off the bottom, then a strong midrange.",{'peak_hp':56.95},'MEASURED',s,'high')
R('setups','2014 FC 450 tester settings',['FC 450'],[2014],"A magazine test crew's 2014 FC 450 setup: fork 0.50 kg/mm springs, 390 cc oil (380 for a plusher feel, 400-410 for a firmer one), compression 9 clicks out (stock 12), rebound 12 out, legs 5 mm up. Shock 5.7 kg/mm spring (stiffer over 200 lb), 100 mm sag (stock 105), high-speed compression 1-1/2 turns out (stock 2), low-speed 12 clicks out, rebound 15 out. Stock rear sprocket is 52 teeth.",{'fork':'0.50 kg/mm, 390 cc, comp 9 out (stock 12), reb 12 out, 5 mm up','shock':'5.7 kg/mm, sag 100 mm, HSC 1-1/2 turns, LSC 12 out, reb 15 out'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2015 Husqvarna FC450 test","https://motocrossactionmag.com/2015-test-ride-husqvarna-fc450","2014")
R('power_feel','2015 FC 450 dyno and price',['FC 450'],[2015],"On a magazine dyno the 2015 FC 450 made 56.48 hp. Peak power matches the KTM, but the sealed airbox makes the low-to-mid response feel choked. List price $9,149.",{'peak_hp':56.48,'msrp_usd':9149},'MEASURED',s2,'high')
R('setups','2015 FC 450 tester settings (4CS)',['FC 450'],[2015],"A magazine test crew's 2015 FC 450 setup: fork 4.8 N/mm springs, oil height 95 mm (stock 100), compression 17 clicks out (stock 15), rebound 17 out (stock 15), legs 5 mm up. Shock 5.7 kg/mm spring, 100 mm sag, high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15).",{'fork':'oil 95 mm (stock 100), comp 17 out, reb 17 out, 5 mm up','shock':'5.7 kg/mm, sag 100 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out (stock 15)'},'TUNER',s2)
s3=F.src(M,"Motocross Action - 2017 Husqvarna FC450 race test","https://motocrossactionmag.com/mxa-race-test-2017-husqvarna-fc450","2016")
R('power_feel','2017-2018 FC 450 dyno and weight',['FC 450'],[2017,2018],"On a magazine dyno the 2017 FC 450 made 57.10 hp at 9,300 rpm, 0.78 hp less than the 2017 KTM 450 SX-F, and weighed 224 lb, 2 lb more. The delivery is smoother and more metered than the KTM's from low to mid. List price $9,499 in 2017.",{'peak_hp':57.1,'peak_rpm':9300,'weight_lb':224,'msrp_usd_2017':9499},'MEASURED',s3,'high')
R('setups','2017-2018 FC 450 tester settings (AER)',['FC 450'],[2017,2018],"A magazine test crew's 2017-2018 FC 450 setup: fork air 140 psi (stock 156), compression 15 clicks out on the 2017 and 18 out on the 2018 (stock 12), rebound 15 out, legs at the third line. Shock stock 45 N/mm spring, 105 mm sag (stock 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15-20 clicks out, rebound 10 out (stock 15). Testers added one tooth at the rear and raced map 2.",{'fork_psi':'140 (stock 156)','fork':'comp 15-18 out (stock 12), reb 15 out, third line','shock':'45 N/mm, sag 105 mm, HSC 1-3/4 turns, LSC 15-20 out, reb 10 out'},'TUNER',s3)
R('ecu_electronics','2017-2018 FC electronics',FC,[2017,2018],"The 2017-2018 FC models have the left-bar multi-switch: map 1 standard, map 2 aggressive (the 2016 switch offered a third), traction control on the upper button and launch control by pressing both buttons together. Launch control cuts power above 7,000 rpm and is for concrete or hard-pack gates; traction control is worth using only on dry hardpack or in deep mud.",{'map_1':'standard','map_2':'aggressive','launch_control':'cuts above 7,000 rpm'},'TUNER',s3)
s4=F.src(M,"Motocross Action - 2019 Husqvarna FC450 race test","https://motocrossactionmag.com/mxa-race-test-the-real-test-of-the-2019-husqvarna-fc450","2018")
R('identity','2019 FC 450 changes',['FC 450'],[2019],"The 2019 FC 450 took the 2019 KTM changes: a frame 10% stiffer in torsion, a head 15 mm lower and 1 lb lighter, Pankl gears on the same ratios, radiators 12 mm lower with 20% more coolant, and a two-piece subframe in place of the three-piece. It keeps the Magura clutch, has Pro Taper bars in a new bend, and its muffler has a restrictor cone worth about 1 hp against the KTM's straight-through one.",{'subframe':'two-piece composite'},'OEM',s4)
R('power_feel','2019 FC 450 dyno and weight',['FC 450'],[2019],"On a magazine dyno the 2019 FC 450 peaked at 56.40 hp with the stock airbox and weighed 224 lb, the second-lightest 450 of its year. Broad and mellow with no hit; opening the airbox (1 in holes into the subframe section behind the filter) and a straight-through muffler wake it up.",{'peak_hp':56.4,'weight_lb':224},'MEASURED',s4,'high')
R('setups','2019 FC 450 tester settings (AER)',['FC 450'],[2019],"A magazine test crew's 2019 FC 450 setup: fork air 145 psi (stock 152), compression 25 clicks out (stock 15), rebound 17 out (stock 15), legs at the third line. Shock stock 45 N/mm spring (42 under 150 lb, 48 over 185 lb), 105 mm sag (WP says 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15). Launch control: hold the TC and map buttons for 2 seconds until the light flashes.",{'fork_psi':'145 (stock 152)','fork':'comp 25 out (stock 15), reb 17 out (stock 15), third line','shock':'45 N/mm, sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out'},'TUNER',s4)

# ---------------- FC 250
s=F.src(M,"Motocross Action - 2014 Husqvarna FC250 test","https://motocrossactionmag.com/mxa-motocross-test-2014-husqvarna-fc250","2013")
R('power_feel','2014 FC 250 dyno and price',['FC 250'],[2014,2015],"On a magazine dyno the 2014 FC 250 made 42.92 hp at 13,500 rpm, the same as the KTM 250 SX-F. A fast, high-revving engine. List price $8,049 in 2014.",{'peak_hp':42.92,'peak_rpm':13500,'msrp_usd_2014':8049},'MEASURED',s,'high')
R('setups','2014 FC 250 tester settings',['FC 250'],[2014],"A magazine test crew's 2014 FC 250 setup: fork 0.46 kg/mm springs, 375 cc oil (stock 390), compression 11 clicks out (stock 12), rebound 10 out (stock 12), legs 5 mm up. Shock 5.4 kg/mm spring, 105 mm sag, high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out (stock 16), rebound 13 out (stock 15). Add one or two teeth at the rear. On this year map 1 is the aggressive map and map 2 the mellow one for hardpack.",{'fork':'375 cc (stock 390), comp 11 out, reb 10 out, 5 mm up','shock':'5.4 kg/mm, sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 13 out'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2016 Husqvarna FC250 race test","https://motocrossactionmag.com/mxa-race-test-2016-husqvarna-fc250","2015")
R('power_feel','2016-2018 FC 250 dyno and weight',['FC 250'],[2016,2017,2018],"On a magazine dyno the 2016 FC 250 made 44.38 hp (the KTM 250 SX-F 43.76), and 44.67 with the airbox cover propped open; the 2018 was quoted at 44.38 hp and 20.73 lb-ft. It weighed 223 lb in 2016 and 220 lb in 2018 with the air fork, 2 lb more than the KTM. Soft low down with a long climb to its power near the 14,000 rpm limit. List price $8,499 in 2016.",{'peak_hp':44.38,'peak_torque_lbft':20.73,'weight_lb_2016':223,'weight_lb_2018':220,'msrp_usd_2016':8499},'MEASURED',s2,'high')
R('setups','2016 FC 250 tester settings (4CS)',['FC 250'],[2016],"A magazine test crew's 2016 FC 250 setup: fork 4.6 N/mm springs, compression 12 clicks out (stock 15), rebound 10 out (stock 15), legs 5 mm up, 10 cc more oil for fast riders. Shock 45 N/mm spring, 105 mm sag, high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15). Stock gearing 13/50; vets and novices ran 13/51. The 2016 map switch reaches two maps chosen by a dial in the airbox; forward is always the stock map.",{'fork':'comp 12 out (stock 15), reb 10 out (stock 15), 5 mm up','shock':'45 N/mm, sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out','gearing':'13/51 (stock 13/50)'},'TUNER',s2)
s3=F.src(M,"Motocross Action - 2018 Husqvarna FC250 race test","https://motocrossactionmag.com/mxa-race-test-2018-husqvarna-fc250","2017")
R('setups','2017-2018 FC 250 tester settings (AER)',['FC 250'],[2017,2018],"A magazine test crew's 2018 FC 250 setup: fork air 150 psi (stock 156), compression 20 clicks out (stock 17), rebound 15 out (stock 17), legs at the third line (3 mm higher if it stands up mid-corner). Shock 42 N/mm spring, 102 mm sag. Stock gearing is 14/51; use a 13-tooth countershaft or a 53 rear. Map 2 was the only map testers raced.",{'fork_psi':'150 (stock 156)','fork':'comp 20 out (stock 17), reb 15 out (stock 17), third line','shock':'42 N/mm, sag 102 mm','gearing':'13/51 or 14/53 (stock 14/51)'},'TUNER',s3,'medium','Tested on the 2018; the 2017 FC 250 has the same engine and the first-year AER fork.')

# ---------------- FC 350
s=F.src(M,"Motocross Action - 2015 Husqvarna FC350 test","https://motocrossactionmag.com/2015-test-ride-husqvarna-fc350","2014")
R('identity','2015 FC 350 in the US',['FC 350'],[2015],"2015 was the first year the FC 350 was sold in the US. The engine is the KTM 350 SX-F's; the sealed airbox cover costs about 1 hp on the dyno and softens the low-to-mid, with the same peak arriving a couple of hundred rpm later.",{'airbox_loss_hp':'about 1'},'MEASURED',s)
R('setups','2015 FC 350 tester settings (4CS)',['FC 350'],[2015],"A magazine test crew's 2015 FC 350 setup: fork 4.8 N/mm springs, oil height 100 mm (lower it 5 mm for pros and 10 mm for slower riders against harshness), compression 17 clicks out (stock 15), rebound 14 out (stock 15), legs 5 mm up. Shock 5.7 kg/mm spring, 100 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out, rebound 13 out (stock 15). Stock rear sprocket is 50: faster riders stayed there or went to 49, slower riders to 51.",{'fork':'comp 17 out (stock 15), reb 14 out, 5 mm up','shock':'5.7 kg/mm, sag 100 mm, HSC 2 turns, LSC 15 out, reb 13 out','gearing':'stock 50T; 49 or 51'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2017 Husqvarna FC350 race test","https://motocrossactionmag.com/mxa-race-test-2017-husqvarna-fc350","2016")
R('power_feel','2017-2018 FC 350 dyno and weight',['FC 350'],[2016,2017,2018],"On a magazine dyno the 2017 FC 350 made 54.75 hp at 13,400 rpm and weighed 221 lb. Smooth, with its best power right at the 13,400 rpm limit.",{'peak_hp':54.75,'peak_rpm':13400,'weight_lb':221},'MEASURED',s2,'high','Measured on the 2017; the 2016-2018 FC 350 share this engine.')
R('setups','2017-2018 FC 350 tester settings (AER)',['FC 350'],[2017,2018],"A magazine test crew's 2017 FC 350 setup: fork air 140 psi (stock 154), compression 20 clicks out, rebound 15 out, legs at the third line; lighter riders lower the damping-leg oil 10 mm or more. Shock stock 42 N/mm spring (was 48 in 2016), 105 mm sag (stock 110), high-speed compression 1-3/4 turns out (stock 2), low-speed 15 clicks out, rebound 10 out (stock 15). Stock rear sprocket 50; half the testers added a tooth, some two. On a cold morning tap the starter briefly a few times to warm the battery before cranking.",{'fork_psi':'140 (stock 154)','fork':'comp 20 out, reb 15 out, third line','shock':'42 N/mm, sag 105 mm, HSC 1-3/4 turns, LSC 15 out, reb 10 out','gearing':'stock 50T; 51 or 52'},'TUNER',s2)

# ---------------- TC 250 / TC 125 two-strokes
TC=['TC 250','TC 125']
s=F.src(M,"Motocross Action - 2014 Husqvarna TC250 test","https://motocrossactionmag.com/2014-test-ride-husqvarna-tc250-two-stroke","2013")
R('identity','2014-2016 TC two-strokes against the KTM SX',TC,[2014,2015,2016],"The 2014-2016 Husqvarna TC 250 and TC 125 are the KTM SX two-strokes of the same year with a polyamide composite subframe, a larger one-piece airbox cover and side panel, D.I.D DirtStar rims, a 20 mm rear axle on 2014 bikes (KTM 25 mm), two seat bolts, hand guards, their own tank (KTM shrouds do not fit) and a handlebar map switch where the KTM has a plug under the tank. Engine, carburettor and jetting are the KTM's.",{'subframe':'polyamide composite','map_switch':'on the handlebar'},'OEM',s)
R('setups','2014 TC 250 tester settings and jetting',['TC 250'],[2014],"A magazine test crew's 2014 TC 250 setup: fork 0.46 kg/mm springs, 370 cc oil (stock 380), compression 7 clicks out (stock 12), rebound 12 out, legs 5 mm up (flush in sand). Shock 5.4 kg/mm spring, 105 mm sag, high-speed compression 2 turns out, with a link 1.25 mm longer. Jetting (36 mm Keihin PWK): 158 main (160 in cold weather), 40 pilot (stock 42), N1EH needle on the 4th clip (N1EG in cold weather), air screw 1-1/2 turns (stock 2). Stock gearing 13/48. It makes just under 50 hp; list price about $7,200.",{'fork':'0.46 kg/mm, 370 cc, comp 7 out (stock 12), reb 12 out, 5 mm up','shock':'5.4 kg/mm, sag 105 mm, HSC 2 turns, link +1.25 mm','jetting':'158 main, 40 pilot, N1EH 4th clip, air screw 1-1/2','gearing':'13/48'},'TUNER',s)
s2=F.src(M,"Motocross Action - 2017 Husqvarna TC250 race test","https://motocrossactionmag.com/mxa-race-test-2017-husqvarna-tc250-two-stroke","2016")
R('identity','2017-2018 TC 250 against the KTM 250 SX',['TC 250'],[2017,2018],"The 2017 TC 250 shares the new 2017 KTM 250 SX engine, chassis and WP AER 48 fork, with a three-piece composite subframe and a more restrictive airbox, a Magura clutch (KTM Brembo), Pro Taper bars (KTM Neken), D.I.D DirtStar rims, GFK discs and a seat 1.5 in longer. The airbox takes some of the edge off the midrange hit. 212 lb, 1 lb more than the KTM; list price $7,799.",{'weight_lb':212,'msrp_usd_2017':7799,'carb':'Mikuni TMX 38'},'OEM',s2)
R('setups','2017-2018 TC 250 tester settings and jetting',['TC 250'],[2017,2018],"A magazine test crew's 2017 TC 250 setup: fork air 144 psi (it bottoms below that), compression 23 clicks out (stock 12), rebound 19 out (stock 12), legs at the second line. Shock 42 N/mm spring, 107 mm sag, high-speed compression 1-1/4 turns out (stock 2), low-speed 8 clicks out (stock 15), rebound 14 out (stock 15). Jetting (Mikuni TMX 38): 450 main (stock 440), 42.5 pilot, 43-73 needle on the 3rd clip, air screw 2-1/2 turns (stock 1). Rear sprocket 49 in place of 50; second to third is a short gap. Unplugging the white connector under the tank gives the mellow ignition map.",{'fork_psi':144,'fork':'comp 23 out (stock 12), reb 19 out (stock 12), second line','shock':'42 N/mm, sag 107 mm, HSC 1-1/4 turns, LSC 8 out, reb 14 out','jetting':'450 main (stock 440), 42.5 pilot, 43-73 3rd clip, air screw 2-1/2','gearing':'14/49 (stock 14/50)'},'TUNER',s2)
s3=F.src(M,"Motocross Action - 2019 Husqvarna TC250 race test","https://motocrossactionmag.com/mxa-race-test-2019-husqvarna-tc250-tw0-stroke","2018")
R('identity','2019 TC 250 changes',['TC 250'],[2019],"2019 TC 250 changes: a two-piece composite airbox and subframe, the stiffer 2019 frame with aluminium head stays, welded aluminium silencer brackets in place of rubber, a new Pro Taper bar bend, and a tamer delivery with the same peak power as the KTM. 212 lb; list price $8,299. Husqvarna said the Magura slave-seal problem was fixed for 2020.",{'weight_lb':212,'msrp_usd':8299},'OEM',s3)
R('setups','2019 TC 250 tester settings and jetting',['TC 250'],[2019],"A magazine test crew's 2019 TC 250 setup: fork air 144 psi (stock 151), compression 32 clicks out (stock 15), rebound 15 out, legs at the first line (stock second); new forks need 2-4 hours to break in. Shock 42 N/mm spring, 105 mm sag, high-speed compression 1-1/2 turns out, low-speed 16 clicks out, rebound 14 out. Jetting: 450 main, 35 pilot, 6BFY43-71 needle on the 3rd clip, air screw 1-1/2 turns; the manual says 60:1 premix and it ran crispest there, though the crew preferred the protection of 40:1. Gearing 14/49 in place of 14/50. Power valve: counter-clockwise for more hit and top end, clockwise for a mellower bottom.",{'fork_psi':'144 (stock 151)','fork':'comp 32 out (stock 15), reb 15 out, first line','shock':'42 N/mm, sag 105 mm, HSC 1-1/2 turns, LSC 16 out, reb 14 out','jetting':'450 main, 35 pilot, 6BFY43-71 3rd clip, air screw 1-1/2','premix':'60:1 per manual','gearing':'14/49 (stock 14/50)'},'TUNER',s3)
s4=F.src(M,"Motocross Action - 2017 Husqvarna TC125 race test","https://motocrossactionmag.com/mxa-race-test-2017-husqvarna-tc125","2016")
R('power_feel','2017-2018 TC 125 power and weight',['TC 125'],[2017,2018],"The 2017-2018 TC 125 makes about 37 hp and weighs 195 lb. The engine is the KTM 125 SX's, but the sealed airbox makes it slower to reach the meat of its power; once there it pulls hard to the top. List price $6,999 in 2017.",{'peak_hp':'about 37','weight_lb':195,'msrp_usd_2017':6999},'MEASURED',s4)
R('setups','2017 TC 125 tester settings and jetting',['TC 125'],[2017],"A magazine test crew's 2017 TC 125 setup: fork air 123 psi for 155-170 lb riders and 125 psi for 170-200 lb, compression 20 clicks out (stock 12), rebound 11 out (stock 12), stock height. Shock 42 N/mm spring, 108 mm sag (stock 110), high-speed compression 2-1/2 turns out (stock 2), low-speed 12 clicks out (stock 15), rebound 15 out. Jetting at 60:1 premix: 480 main, 32 pilot (stock 45), 6BFY43-74 needle on the 3rd clip, air screw 1 turn (stock 1-1/2). The thin stock tubes leak; fit heavy-duty ones.",{'fork_psi':'123-125','fork':'comp 20 out (stock 12), reb 11 out','shock':'42 N/mm, sag 108 mm, HSC 2-1/2 turns, LSC 12 out, reb 15 out','jetting':'480 main, 32 pilot (stock 45), 6BFY43-74 3rd clip, air screw 1 turn','premix':'60:1'},'TUNER',s4)
s5=F.src(M,"Motocross Action - 2018 Husqvarna TC125 race test","https://motocrossactionmag.com/mxa-motocross-race-test-2018-husqvarna-tc125-tw0-stroke","2017")
R('setups','2018 TC 125 tester settings and jetting',['TC 125'],[2018],"A magazine test crew's 2018 TC 125 setup: fork air 127 psi (stock 124; 130 for 170-200 lb riders), compression 24 clicks out (stock 12), rebound 15 out (stock 12), legs at the first line. Shock stock 42 N/mm spring, 105 mm sag, high-speed compression 2 turns out, low-speed 15 clicks out, rebound 15 out. For 2018 the recommended premix changed from 60:1 to 40:1 with a 480 main, 35 pilot and 6BFY42-75 needle; testers ran a 490 main, 3rd clip, air screw 2 turns. Rear sprocket 51 in place of 50. For more low-end, cut the right side of the airbox and drill the left side behind the filter.",{'fork_psi':'127 (stock 124)','fork':'comp 24 out (stock 12), reb 15 out, first line','shock':'42 N/mm, sag 105 mm, HSC 2 turns, LSC 15 out, reb 15 out','jetting':'490 main (stock 480), 35 pilot, 6BFY42-75 3rd clip, air screw 2 turns','premix':'40:1','gearing':'51T rear (stock 50T)'},'TUNER',s5)

if __name__=='__main__': F.write()
